    def _timeout(self) -> None:
        if self._deadline != math.inf:
            loop = get_running_loop()
            if loop.time() >= self._deadline:
                self.cancel()
            else:
                self._timeout_handle = loop.call_at(self._deadline, self._timeout)

    def _prune_scope_tree(self) -> None:
        # A task group exits its scope before waiting for its children. Keep the
        # scope linked until all its tasks and descendant scopes have finished.
        scope = self
        while (
            scope._parent_scope is not None
            and not scope._tasks
            and not scope._child_scopes
        ):
            scope._parent_scope._child_scopes.discard(scope)
            scope = scope._parent_scope

    def _deliver_cancellation(self, origin: CancelScope | None = None) -> bool:
        """
        Deliver cancellation to directly contained tasks and nested cancel scopes.

        Schedule another run at the end if we still have tasks eligible for
        cancellation.
        """
        if origin is None:
            origin = self

        should_retry = False
        current = current_task()
        for task in self._tasks:
            # Tasks also remain registered in their task group's scope while they
            # enter nested scopes. Deliver only from their current scope so that
            # shielding one task cannot hide its unshielded siblings.
            if task.done() or _task_states[task].cancel_scope is not self:
                continue

            should_retry = True
            if task._must_cancel:  # type: ignore[attr-defined]
                continue

            if task is not current and (
                task is self._host_task or _task_started(task)
            ):
                waiter = task._fut_waiter  # type: ignore[attr-defined]
                if not isinstance(waiter, asyncio.Future) or not waiter.done():
                    if task is origin._host_task:
                        origin._cancel_calls += 1
                    if sys.version_info >= (3, 9):
                        task.cancel(f"Cancelled by cancel scope {id(origin):x}")
                    else:
                        task.cancel()

        for scope in self._child_scopes:
            if not scope._shield:
                should_retry = scope._deliver_cancellation(origin) or should_retry

        # Only the originating scope owns the retry callback.
        if origin is self:
            if should_retry:
                self._cancel_handle = get_running_loop().call_soon(
                    self._deliver_cancellation
                )
            else:
                self._cancel_handle = None

        return should_retry

